import {registerMarkup} from './register.js';
import {catalogue,cleanCart,lines,totals,money,bundleOptions,cartKey} from './shop-core.js';
const KEY='kassakompas.shop.cart.v1';
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let memory=[],storageAvailable=true,toastTimer;
try{memory=cleanCart(JSON.parse(localStorage.getItem(KEY)||'[]'));}catch{storageAvailable=false;}
function cart(){return memory;}
function save(value){memory=cleanCart(value);try{localStorage.setItem(KEY,JSON.stringify(memory));}catch{storageAvailable=false;}updateCount();}
function updateCount(){document.querySelectorAll('[data-cart-count]').forEach(el=>el.textContent=cart().reduce((n,r)=>n+r.quantity,0));}
function announce(message){const t=document.querySelector('#shop-status');if(!t)return;t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4500);}
function costRows(v){return '<dl class="cost-rows">'+(v.once?`<div><dt>Eenmalig</dt><dd>${money(v.once)}</dd></div>`:'')+(v.month?`<div><dt>Per maand</dt><dd>${money(v.month)}</dd></div>`:'')+(v.year?`<div><dt>Per jaar, ineens</dt><dd>${money(v.year)}</dd></div>`:'')+'</dl>';}
function summary(cart,checkout=false){const t=totals(cart),delivery=document.querySelector('[name="delivery"]:checked')?.value;
 return `<h2>${checkout?'Je overzicht':'Besteloverzicht'}</h2>${checkout?lines(cart).map(r=>`<div class="cart-item-summary"><strong>${r.quantity} × ${escape(r.productInfo.name)}</strong>${escape(r.variantInfo.label)}</div>`).join(''):''}<dl class="summary-rows">${t.once?`<div><dt>Eenmalige bedragen</dt><dd>${money(t.once)}</dd></div>`:''}${t.month?`<div><dt>Eerste maand</dt><dd>${money(t.month)}</dd></div>`:''}${t.year?`<div><dt>Eerste jaar</dt><dd>${money(t.year)}</dd></div>`:''}<div><dt>Subtotaal excl. btw</dt><dd>${money(t.net)}</dd></div><div><dt>Btw (21%)</dt><dd>${money(t.vat)}</dd></div><div class="summary-total"><dt>Bij start incl. btw</dt><dd>${money(t.gross)}</dd></div></dl><div class="summary-recurring">${t.month?`<p>Daarna maandelijks: <strong>${money(t.month)} excl. btw</strong></p>`:''}${t.year?`<p>Jaarbedrag: <strong>${money(t.year)} excl. btw</strong></p>`:''}${!t.month&&!t.year?'<p>Geen terugkerende productkosten in deze selectie.</p>':''}</div><p class="summary-note">${delivery==='delivery'?'Eventuele leveringskosten zijn nog niet inbegrepen en worden vooraf bevestigd.':'Afhalen op afspraak: €0. Eventuele levering wordt vooraf besproken.'} De eerste abonnementsperiode is hierboven meegerekend. Dit overzicht is nog geen betalingsbevestiging.</p>${!checkout?'<a class="button primary" href="/shop/afrekenen/">Verder naar bestelgegevens →</a><p class="form-note">Online betalen binnenkort beschikbaar. Je kunt je bestelling nu per e-mail doorgeven.</p>':''}`;
}
function thumb(p,key){if(p.category==='Kassasystemen'||p.category==='Touchscreens')return registerMarkup('cart-'+key.replace(/[^a-z0-9]/gi,''));if(p.image.startsWith('/'))return `<img src="${p.image}" alt="" width="76" height="76">`;return `<div class="product-symbol"><svg viewBox="0 0 100 85" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="18" y="10" width="64" height="48" rx="4"/><path d="M50 58v15M35 74h30M30 26h40M30 37h26"/></svg></div>`;}
function describe(v,quantity=1){return [v.once?money(v.once*quantity)+' eenmalig':'',v.month?money(v.month*quantity)+' / maand':'',v.year?money(v.year*quantity)+' / jaar':''].filter(Boolean).join(' + ');}
function renderCart(){const target=document.querySelector('#cart-content');if(!target)return;const data=lines(cart());
 if(!data.length){target.innerHTML='<div class="empty-state"><h2>Je winkelmandje is nog leeg</h2><p>Bekijk ons assortiment en stel je kassaopstelling samen.</p><a class="button primary" href="/shop/">Verder winkelen →</a></div>';return;}
 target.innerHTML='<div class="cart-grid"><div>'+data.map(r=>`<article class="cart-line" data-key="${r.key}"><a href="/shop/${r.product}/" class="cart-thumbnail" aria-label="${escape(r.productInfo.name)}">${thumb(r.productInfo,r.key)}</a><div><h2><a href="/shop/${r.product}/">${escape(r.productInfo.name)}</a></h2><p>${escape(r.variantInfo.label)}</p><p class="line-price">${describe(r.variantInfo,r.quantity)}</p><p>Excl. btw · ${escape(r.variantInfo.notes)}</p><div class="quantity-controls"><button type="button" data-change="-1" aria-label="Minder ${escape(r.productInfo.name)}" ${r.quantity===1?'disabled':''}>−</button><output aria-label="Aantal ${escape(r.productInfo.name)}">${r.quantity}</output><button type="button" data-change="1" aria-label="Meer ${escape(r.productInfo.name)}" ${r.quantity===99?'disabled':''}>+</button><button type="button" class="remove-item" data-remove aria-label="Verwijder ${escape(r.productInfo.name)}">Verwijderen</button></div></div></article>`).join('')+'<a class="cart-continue" href="/shop/">← Verder winkelen</a></div><aside class="order-summary">'+summary(cart())+'</aside></div>';
 initRegisterScreens(target);
 target.querySelectorAll('[data-change],[data-remove]').forEach(button=>button.addEventListener('click',()=>{const key=button.closest('[data-key]').dataset.key,name=button.getAttribute('aria-label');const rows=cart().map(r=>({...r}));const i=rows.findIndex(r=>cartKey(r)===key);if(i<0)return;if(button.hasAttribute('data-remove'))rows.splice(i,1);else rows[i].quantity+=Number(button.dataset.change);save(rows);renderCart();announce('Winkelmandje bijgewerkt.');if(button.hasAttribute('data-remove'))document.querySelector('#cart-content .button, #cart-content .cart-line a')?.focus();else document.querySelector(`[aria-label="${CSS.escape(name)}"]`)?.focus();}));
}
updateCount();
window.addEventListener('storage',event=>{if(event.key!==KEY)return;try{memory=cleanCart(JSON.parse(event.newValue||'[]'));}catch{memory=[];}updateCount();renderCart();renderCheckout();});
const productForm=document.querySelector('#product-form');
if(productForm){const product=catalogue.find(p=>p.id===productForm.dataset.product),select=productForm.elements.variant;
 const options=bundleOptions(product.id);
 if(options){const box=document.createElement('fieldset');box.className='bundle-options';box.innerHTML='<legend>Maak je bundel compleet</legend><p>'+(options.extra?'De standaardsoftware van deze bundel blijft inbegrepen. Kies hieronder eventueel een extra licentie.':'Kies de gewenste softwarelicentie en eventueel installatie.')+'</p><label class="field">'+(options.extra?'Extra licentie':'Softwarelicentie')+'<select id="bundle-license"><option value="">'+(options.extra?'Geen extra licentie':'Geen licentie toevoegen')+'</option>'+options.licenses.map(([id,variant])=>{const p=catalogue.find(p=>p.id===id),v=p.variants.find(v=>v.id===variant);return '<option value="'+id+':'+variant+'">'+escape(p.name)+' — '+escape(v.label)+' ('+describe(v)+')</option>';}).join('')+'</select></label>'+(options.installation?'<label class="check-option"><input type="checkbox" id="bundle-installation"><span>Installatie ter plaatse toevoegen <strong>+ '+money(39500)+' eenmalig excl. btw</strong></span></label>':'<p>Installatie en instructie zijn al inbegrepen.</p>');productForm.querySelector('.detail-price').before(box);}
 const selectedAddons=()=>{const a=[],license=productForm.querySelector('#bundle-license')?.value;if(license){const [product,variant]=license.split(':');a.push({product,variant});}if(productForm.querySelector('#bundle-installation')?.checked)a.push({product:'installatie',variant:'eenmalig'});return a;};
 const update=()=>{const base=product.variants.find(v=>v.id===select.value),v=lines([{product:product.id,variant:base.id,quantity:1,addons:selectedAddons()}])[0].variantInfo;const main=product.id==='pax-a77'?(v.id==='koop'?49500:3600):(base.once||base.month||base.year);document.querySelector('#variant-price').innerHTML=`<strong>${money(main)}</strong><span>${product.id==='pax-a77'?(v.id==='koop'?'aankoop toestel':'per maand huur'):base.once?'eenmalig':base.month?'per maand':'per jaar, ineens'}</span>`;document.querySelector('#variant-costs').innerHTML=costRows(v);document.querySelector('#variant-notes').textContent=v.notes;if(options){let total=document.querySelector('#bundle-start-total');if(!total){total=document.createElement('p');total.id='bundle-start-total';total.className='bundle-start-total';document.querySelector('#variant-costs').after(total);}total.textContent='Bundel bij start: '+money(v.once+v.month+v.year)+' excl. btw per opstelling';}};
 select.addEventListener('change',update);productForm.querySelectorAll('.bundle-options select,.bundle-options input').forEach(x=>x.addEventListener('change',update));update();
 productForm.addEventListener('submit',e=>{e.preventDefault();if(!productForm.reportValidity())return;const quantity=Number(productForm.elements.quantity.value);if(!Number.isInteger(quantity)||quantity<1||quantity>99)return;const row={product:product.id,variant:select.value,quantity,addons:selectedAddons()};save([...cart(),row]);announce(product.name+' toegevoegd aan je winkelmandje.'+(storageAvailable?'':' Opslag is geblokkeerd: houd deze pagina open.'));let link=document.querySelector('#added-cart-link');if(!link){link=document.createElement('a');link.id='added-cart-link';link.className='cart-continue';link.href='/shop/winkelmandje/';link.textContent='Bekijk je winkelmandje →';productForm.append(link);}});
}
const search=document.querySelector('#product-search');
if(search){let category='Alle producten';const buttons=[...document.querySelectorAll('[data-filter]')],cards=[...document.querySelectorAll('.product-card')];
 const filter=()=>{const q=search.value.trim().toLocaleLowerCase('nl');let n=0;cards.forEach(card=>{const show=(category==='Alle producten'||card.dataset.category===category)&&card.textContent.toLocaleLowerCase('nl').includes(q);card.hidden=!show;if(show)n++;});document.querySelector('#result-count').textContent=n+' '+(n===1?'product':'producten')+' · prijzen excl. btw';document.querySelector('#no-results').hidden=n!==0;};
 buttons.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;buttons.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filter();}));search.addEventListener('input',filter);document.querySelector('#reset-search').addEventListener('click',()=>{search.value='';buttons[0].click();search.focus();});
}
renderCart();
function renderCheckout(){const target=document.querySelector('#checkout-summary');if(!target)return;const empty=!cart().length;document.querySelector('#checkout-empty').hidden=!empty;document.querySelector('#checkout-layout').hidden=empty;target.innerHTML=empty?'':summary(cart(),true);}
renderCheckout();
const checkoutForm=document.querySelector('#checkout-form');
if(checkoutForm){checkoutForm.querySelectorAll('[name="delivery"]').forEach(x=>x.addEventListener('change',renderCheckout));checkoutForm.addEventListener('submit',event=>{
 event.preventDefault();if(!checkoutForm.reportValidity()||!cart().length)return;
 const d=new FormData(checkoutForm),t=totals(cart());const sections=['BESTELAANVRAAG KASSAKOMPAS — nog te bevestigen','','Bedrijf: '+d.get('company'),'Contact: '+d.get('name'),'Btw-/ondernemingsnummer: '+d.get('vat'),'E-mail: '+d.get('email'),'Telefoon: '+d.get('phone'),'Facturatieadres: '+[d.get('address'),d.get('postcode'),d.get('city'),d.get('country')].join(', '),'Afhandeling: '+(d.get('delivery')==='pickup'?'Afhalen op afspraak (€0)':'Levering bespreken — kosten op bevestiging'),'','PRODUCTEN'];
 lines(cart()).forEach(r=>sections.push(r.quantity+' × '+r.productInfo.name+' — '+r.variantInfo.label,describe(r.variantInfo,r.quantity)+' excl. btw',r.variantInfo.notes,''));sections.push('Eenmalig excl. btw: '+money(t.once),'Eerste maand excl. btw: '+money(t.month),'Eerste jaar excl. btw: '+money(t.year),'Subtotaal excl. btw: '+money(t.net),'Btw (21%): '+money(t.vat),'Bij start incl. btw: '+money(t.gross),'Daarna per maand excl. btw: '+money(t.month),'Jaarbedrag excl. btw: '+money(t.year),'Eventuele leveringskosten nog te bevestigen.','','Opmerking: '+(d.get('message')||'—'),'','Dit is een aanvraag. Er werd geen online betaling uitgevoerd. Graag uw bevestiging van beschikbaarheid, uitvoering, eventuele leveringskosten en abonnementsvoorwaarden.');
 const body=sections.join('\r\n'),status=document.querySelector('#checkout-status');status.hidden=false;status.textContent='Je e-mail is voorbereid. Verstuur hem in je e-mailprogramma; wij hebben je aanvraag pas na verzending ontvangen. Er is nog niets betaald. Je winkelmandje blijft bewaard.';
 let controls=document.querySelector('#order-export');if(!controls){controls=document.createElement('div');controls.id='order-export';status.after(controls);}controls.innerHTML='';const download=document.createElement('a');download.className='cart-continue';download.textContent='Download je besteloverzicht (.txt)';download.download='KassaKompas-bestelaanvraag.txt';download.href=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'}));controls.append(download);
 const link=document.createElement('a');link.href='mailto:sales@kassakompas.com?subject='+encodeURIComponent('Bestelaanvraag shop — '+String(d.get('company')).slice(0,100))+'&body='+encodeURIComponent(body);link.target='_blank';link.rel='noopener';document.body.append(link);link.click();link.remove();
 });}
// Reuse the exact approved register geometry in catalogue, details and cart.
function fitRegister(stage){const [a,b,c,d,e,f,g,h]=JSON.parse(stage.dataset.screenMap);const scale=stage.getBoundingClientRect().width/Number(stage.dataset.photoWidth);stage.querySelector('.register-display').style.transform='matrix3d('+[a*scale,d*scale,0,g,b*scale,e*scale,0,h,0,0,1,0,c*scale,f*scale,0,1].join(',')+')';}
function initRegisterScreens(scope=document){const stages=[...scope.querySelectorAll('[data-screen-map]')];stages.forEach(fitRegister);if('ResizeObserver'in window){if(!initRegisterScreens.observer)initRegisterScreens.observer=new ResizeObserver(entries=>entries.forEach(e=>fitRegister(e.target)));stages.forEach(s=>initRegisterScreens.observer.observe(s));}}
initRegisterScreens();
